begin;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to authenticated,service_role;
set search_path=public,extensions;
select extensions.no_plan();
insert into auth.users(id,raw_user_meta_data) values ('ab000000-0000-4000-8000-000000000001','{"display_name":"Chat owner"}'),('ab000000-0000-4000-8000-000000000002','{"display_name":"Other chat user"}');
create temporary table chat_state(id uuid,response jsonb);
grant all on chat_state to authenticated,service_role;
set local role authenticated;
select set_config('request.jwt.claim.sub','ab000000-0000-4000-8000-000000000001',true);
insert into chat_state(id) select public.open_conversation('51000000-0000-4000-8000-000000000001');
select extensions.is(public.open_conversation('51000000-0000-4000-8000-000000000001'),(select id from chat_state),'Opening a conversation resumes the owner session');
select extensions.throws_ok($$select public.reserve_ai_turn('ab000000-0000-4000-8000-000000000001',(select id from chat_state),'ab100000-0000-4000-8000-000000000001','Hello')$$,'42501',null,'Learners cannot bypass the AI Edge Function');
set local role service_role;
update chat_state set response=public.reserve_ai_turn('ab000000-0000-4000-8000-000000000001',id,'ab100000-0000-4000-8000-000000000001','Hello');
select extensions.is((select response#>>'{context,name}' from chat_state),'Haruka','Trusted AI reservation resolves the published character');
select extensions.throws_ok($$select public.reserve_ai_turn('ab000000-0000-4000-8000-000000000002',(select id from chat_state),'ab100000-0000-4000-8000-000000000002','Hello')$$,'42501','Conversation unavailable','Verified users cannot send to another account conversation');
select extensions.throws_ok($$select public.reserve_ai_turn('ab000000-0000-4000-8000-000000000001',(select id from chat_state),'ab100000-0000-4000-8000-000000000002','Again')$$,'P0001','Wait for your current reply','Concurrent AI requests are serialized before billing');
select extensions.lives_ok($$select public.finish_ai_turn('ab100000-0000-4000-8000-000000000001','こんにちは！')$$,'Trusted AI response commits');
select extensions.is(public.finish_ai_turn('ab100000-0000-4000-8000-000000000001','different')->>'text','こんにちは！','Response retries return the committed reply');
select extensions.is(public.reserve_ai_turn('ab000000-0000-4000-8000-000000000001',(select id from chat_state),'ab100000-0000-4000-8000-000000000001','Hello')->>'cached','true','Request retries do not call the paid provider twice');
set local role authenticated;
select extensions.is((select count(*) from public.conversation_messages),2::bigint,'Conversation persists both actual messages');
select extensions.is((select affinity from public.character_relationships),1,'Relationship progresses once per committed turn');
select extensions.throws_ok($$insert into public.conversation_messages(session_id,role,content) values((select id from chat_state),'assistant','forged')$$,'42501',null,'Learners cannot forge AI responses');
select set_config('request.jwt.claim.sub','ab000000-0000-4000-8000-000000000002',true);
select extensions.is((select count(*) from public.conversation_messages),0::bigint,'Conversation history remains private');
reset role;
select * from extensions.finish();
rollback;
